beforeExample:
import org.junit.Assert;

public class TestClass {
    public void testMethod(Object myObject) {
        Assert.assertNotNull(myObject);
    }
}

afterExample:
import org.junit.Assert;

public class TestClass {
    public void testMethod(Object myObject) {
        Assert.assertNotNull("Assertion failed: Null value detected for " + java.lang.String.valueOf(myObject), myObject);
    }
}

negativeExample:
import org.junit.Assert;

public class TestClass {
    public void testMethod(Object myObject) {
        // Already has a message
        Assert.assertNotNull("Specific message here", myObject);
        // Different assert method
        Assert.assertTrue(myObject != null);
    }
}
